"""GENERATED by tool/gen_jieqi_corrections.py（作者自己的排盤項目）— DO NOT EDIT.

節氣時刻修正表：精確時刻（Skyfield + DE440s 視黃經）與低精度 Meeus 公式
（almanac 同源實現）之差，單位秒。term_time 先算 Meeus 再加此修正；年份
超出 [FIRST_YEAR, LAST_YEAR] 時無修正，退回裸 Meeus。

本文件為獨立拷貝（各後端可能分開部署，不做共用模塊）。
"""

FIRST_YEAR = 1900
LAST_YEAR = 2100


def correction_seconds(year: int, longitude: float) -> int | None:
    """year（UTC 歷年）內黃經 longitude（15°整倍數）節氣的修正秒數。"""
    if year < FIRST_YEAR or year > LAST_YEAR:
        return None
    return _SECONDS[(year - FIRST_YEAR) * 24 + (round(longitude) // 15) % 24]


